    display: flex;
    gap: 12px;
    align-items: center;
  }

  &__avatar {
    width: 48px;
    height: 48px;
    border-radius: 50%;
    object-fit: cover;
  }

  &__info {
    flex: 1;
  }

  &__details {
    margin-top: 12px;
    padding-top: 12px;
    border-top: 1px solid var(--color-border);
  }

  &__actions {
    margin-top: 12px;
    display: flex;
    gap: 8px;
    justify-content: flex-end;
  }

  // Variant modifiers
  &--compact {
    padding: 8px;

    .user-card__avatar {
      width: 32px;
      height: 32px;
    }
  }
}
</style>
```

### 2. Composition API Patterns

Composition API là heart của Vue 3, providing flexible way để organize logic trong components. Để tận dụng tối đa, developers nên follow certain patterns.

**Composable Organization**:

```typescript
// composables/useCounter.ts
import { ref, computed, type Ref } from 'vue'

export interface UseCounterOptions {
  min?: number
  max?: number
  step?: number
}

export function useCounter(initialValue = 0, options: UseCounterOptions = {}) {
  const { min = -Infinity, max = Infinity, step = 1 } = options

  const count = ref(initialValue)

  const increment = () => {
    if (count.value + step <= max) {
      count.value += step
    }
  }

  const decrement = () => {
    if (count.value - step >= min) {
      count.value -= step
    }
  }

  const reset = () => {
    count.value = initialValue
  }

  const setValue = (value: number) => {
    count.value = Math.min(max, Math.max(min, value))
  }

  const isAtMin = computed(() => count.value <= min)
  const isAtMax = computed(() => count.value >= max)

  return {
    count: count as Readonly<Ref<number>>,
    increment,
    decrement,
    reset,
    setValue,
    isAtMin,
    isAtMax
  }
}
```

**Stateful Logic Reuse**:

```typescript
// composables/useAsync.ts
import { ref, shallowRef, isRef, watchEffect, type Ref } from 'vue'

export interface UseAsyncOptions<T> {
  immediate?: boolean
  onError?: (error: Error) => void
  onSuccess?: (data: T) => void
}

export function useAsync<T>(
  asyncFn: () => Promise<T>,
  options: UseAsyncOptions<T> = {}
) {
  const { immediate = true, onError, onSuccess } = options

  const data = shallowRef<T | null>(null)
  const error = shallowRef<Error | null>(null)
  const isLoading = ref(false)
  const isSuccess = ref(false)

  const execute = async (...args: unknown[]) => {
    isLoading.value = true
    error.value = null

    try {
      const result = await asyncFn(...args)
      data.value = result
      isSuccess.value = true
      onSuccess?.(result)
      return result
    } catch (e) {
      const err = e instanceof Error ? e : new Error('Unknown error')
      error.value = err
      isSuccess.value = false
      onError?.(err)
      throw err
    } finally {
      isLoading.value = false
    }
  }

  if (immediate) {
    execute()
  }

  return {
    data: data as Readonly<Ref<T | null>>,
    error: error as Readonly<Ref<Error | null>>,
    isLoading: isLoading as Readonly<Ref<boolean>>,
    isSuccess: isSuccess as Readonly<Ref<boolean>>,
    execute
  }
}

// Usage
const fetchUsers = () => fetch('/api/users').then(r => r.json())
const { data: users, isLoading, error, execute: refreshUsers } = useAsync(fetchUsers)
```

### 3. Pinia State Management

Pinia là official state management library cho Vue 3, cung cấp intuitive API với full TypeScript support. Để maintain scalable state management, follow these patterns.

**Store Structure**:

```typescript
// stores/user.ts
import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import type { User, UserCredentials, UserProfile } from '@/types'

export const useUserStore = defineStore('user', () => {
  // State
  const profile = ref<User | null>(null)
  const token = ref<string | null>(null)
  const isLoading = ref(false)
  const error = ref<Error | null>(null)

  // Getters (Computed)
  const isAuthenticated = computed(() => token.value !== null && profile.value !== null)
  const userRole = computed(() => profile.value?.role ?? 'guest')
  const userFullName = computed(() => {
    if (!profile.value) return ''
    return `${profile.value.firstName} ${profile.value.lastName}`
  })

  // Actions
  const login = async (credentials: UserCredentials): Promise<void> => {
    isLoading.value = true
    error.value = null

    try {
      const response = await fetch('/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(credentials)
      })

      if (!response.ok) {
        throw new Error('Invalid credentials')
      }

      const data = await response.json()
      token.value = data.token
      profile.value = data.user
      localStorage.setItem('auth_token', data.token)
    } catch (e) {
      error.value = e instanceof Error ? e : new Error('Login failed')
      throw error.value
    } finally {
      isLoading.value = false
    }
  }

  const logout = (): void => {
    profile.value = null
    token.value = null
    localStorage.removeItem('auth_token')
  }

  const fetchProfile = async (): Promise<void> => {
    if (!token.value) return

    isLoading.value = true
    error.value = null

    try {
      const response = await fetch('/api/users/me', {
        headers: {
          'Authorization': `Bearer ${token.value}`
        }
      })

      if (!response.ok) {
        throw new Error('Failed to fetch profile')
      }

      profile.value = await response.json()
    } catch (e) {
      error.value = e instanceof Error ? e : new Error('Failed to fetch profile')
    } finally {
      isLoading.value = false
    }
  }

  const updateProfile = async (updates: Partial<UserProfile>): Promise<void> => {
    if (!token.value) throw new Error('Not authenticated')

    isLoading.value = true
    error.value = null

    try {
      const response = await fetch('/api/users/me', {
        method: 'PATCH',
        headers: {
          'Authorization': `Bearer ${token.value}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(updates)
      })

      if (!response.ok) {
        throw new Error('Failed to update profile')
      }

      profile.value = await response.json()
    } catch (e) {
      error.value = e instanceof Error ? e : new Error('Failed to update profile')
      throw error.value
    } finally {
      isLoading.value = false
    }
  }

  // Initialize from localStorage
  const initAuth = (): void => {
    const storedToken = localStorage.getItem('auth_token')
    if (storedToken) {
      token.value = storedToken
      fetchProfile()
    }
  }

  return {
    // State
    profile,
    token,
    isLoading,
    error,
    // Getters
    isAuthenticated,
    userRole,
    userFullName,
    // Actions
    login,
    logout,
    fetchProfile,
    updateProfile,
    initAuth
  }
})
```

**Store Composition Patterns**:

```typescript
// stores/cart.ts - Setup store với cart logic
import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import type { Product, CartItem } from '@/types'

export const useCartStore = defineStore('cart', () => {
  const items = ref<CartItem[]>([])

  // Computed getters
  const itemCount = computed(() =>
    items.value.reduce((sum, item) => sum + item.quantity, 0)
  )

  const subtotal = computed(() =>
    items.value.reduce((sum, item) => sum + item.price * item.quantity, 0)
  )

  const tax = computed(() => subtotal.value * 0.1)
  const total = computed(() => subtotal.value + tax.value)

  const isEmpty = computed(() => items.value.length === 0)

  // Actions
  const addItem = (product: Product, quantity = 1): void => {
    const existingItem = items.value.find(item => item.id === product.id)

    if (existingItem) {
      existingItem.quantity += quantity
    } else {
      items.value.push({
        ...product,
        quantity
      })
    }
  }

  const removeItem = (productId: number): void => {
    const index = items.value.findIndex(item => item.id === productId)
    if (index !== -1) {
      items.value.splice(index, 1)
    }
  }

  const updateQuantity = (productId: number, quantity: number): void => {
    const item = items.value.find(item => item.id === productId)
    if (item) {
      if (quantity <= 0) {
        removeItem(productId)
      } else {
        item.quantity = quantity
      }
    }
  }

  const clearCart = (): void => {
    items.value = []
  }

  return {
    items,
    itemCount,
    subtotal,
    tax,
    total,
    isEmpty,
    addItem,
    removeItem,
    updateQuantity,
    clearCart
  }
})
```

### 4. Vue Router Best Practices

Vue Router là essential cho SPAs, và proper setup là critical cho maintainability và performance.

**Route Definitions**:

```typescript
// router/index.ts
import { createRouter, createWebHistory, type RouteRecordRaw } from 'vue-router'
import { useAuthStore } from '@/stores/auth'

// Lazy load all routes
const routes: RouteRecordRaw[] = [
  {
    path: '/',
    name: 'home',
    component: () => import('@/pages/HomePage.vue'),
    meta: { title: 'Home' }
  },
  {
    path: '/about',
    name: 'about',
    component: () => import('@/pages/AboutPage.vue'),
    meta: { title: 'About Us' }
  },
  {
    path: '/products',
    name: 'products',
    component: () => import('@/pages/ProductsPage.vue'),
    meta: { title: 'Products' }
  },
  {
    path: '/products/:slug',
    name: 'product-detail',
    component: () => import('@/pages/ProductDetailPage.vue'),
    meta: { title: 'Product Details' }
  },
  {
    path: '/cart',
    name: 'cart',
    component: () => import('@/pages/CartPage.vue'),
    meta: { title: 'Shopping Cart' }
  },
  {
    path: '/checkout',
    name: 'checkout',
    component: () => import('@/pages/CheckoutPage.vue'),
    meta: { title: 'Checkout', requiresAuth: true }
  },
  {
    path: '/dashboard',
    component: () => import('@/layouts/DashboardLayout.vue'),
    meta: { requiresAuth: true },
    children: [
      {
        path: '',
        name: 'dashboard',
        component: () => import('@/pages/dashboard/DashboardPage.vue'),
        meta: { title: 'Dashboard' }
      },
      {
        path: 'orders',
        name: 'orders',
        component: () => import('@/pages/dashboard/OrdersPage.vue'),
        meta: { title: 'My Orders' }
      },
      {
        path: 'settings',
        name: 'settings',
        component: () => import('@/pages/dashboard/SettingsPage.vue'),
        meta: { title: 'Settings' }
      }
    ]
  },
  {
    path: '/login',
    name: 'login',
    component: () => import('@/pages/LoginPage.vue'),
    meta: { guestOnly: true, title: 'Login' }
  },
  {
    path: '/register',
    name: 'register',
    component: () => import('@/pages/RegisterPage.vue'),
    meta: { guestOnly: true, title: 'Register' }
  },
  {
    path: '/:pathMatch(.*)*',
    name: 'not-found',
    component: () => import('@/pages/NotFoundPage.vue'),
    meta: { title: 'Page Not Found' }
  }
]

const router = createRouter({
  history: createWebHistory(import.meta.env.BASE_URL),
  routes,
  scrollBehavior(to, from, savedPosition) {
    if (savedPosition) {
      return savedPosition
    } else if (to.hash) {
      return { el: to.hash }
    } else {
      return { top: 0 }
    }
  }
})

// Navigation guards
router.beforeEach(async (to, from, next) => {
  const authStore = useAuthStore()

  // Initialize auth if needed
  if (!authStore.isInitialized) {
    await authStore.initialize()
  }

  // Update document title
  document.title = to.meta.title
    ? `${to.meta.title} | My App`
    : 'My App'

  // Check authentication requirements
  if (to.meta.requiresAuth && !authStore.isAuthenticated) {
    next({ name: 'login', query: { redirect: to.fullPath } })
    return
  }

  // Redirect authenticated users away from guest-only pages
  if (to.meta.guestOnly && authStore.isAuthenticated) {
    next({ name: 'dashboard' })
    return
  }

  next()
})

export default router
```

**Route Types**:

```typescript
// types/router.ts
import type { RouteRecordRaw } from 'vue-router'

export interface RouteMeta {
  title?: string
  requiresAuth?: boolean
  guestOnly?: boolean
  layout?: 'default' | 'dashboard' | 'auth'
  breadcrumb?: BreadcrumbItem[]
  [key: string]: unknown
}

export interface BreadcrumbItem {
  label: string
  to?: string
  active?: boolean
}

// Extend RouteRecordRaw
declare module 'vue-router' {
  interface RouteMeta {
    title?: string
    requiresAuth?: boolean
    guestOnly?: boolean
  }
}
```

## Best Practices for Component Design

### 1. Props and Emits

**Type-Safe Props**:

```typescript
// Define prop types explicitly
interface Props {
  title: string
  count: number
  items: string[]
  user: User
  onClick: () => void
  callback: (value: string) => void
  variant?: 'primary' | 'secondary' | 'danger'
  size?: 'sm' | 'md' | 'lg'
}

// Using defineProps with types
const props = withDefaults(defineProps<Props>(), {
  variant: 'primary',
  size: 'md',
  items: () => [] // Default factory function for arrays
})

// With complex types
const props = defineProps({
  user: {
    type: Object as PropType<User>,
    required: true
  },
  items: {
    type: Array as PropType<string[]>,
    default: () => []
  },
  callback: {
    type: Function as PropType<(value: string) => void>,
    required: true
  }
})
```

**Type-Safe Emits**:

```typescript
// Using defineEmits with type syntax (recommended)
const emit = defineEmits<{
  (e: 'update:modelValue', value: string): void
  (e: 'submit', data: FormData): void
  (e: 'cancel'): void
  (e: 'custom', payload: { id: number; action: string }): void
}>()

// Usage
emit('update:modelValue', 'new value')
emit('submit', { name: 'John', email: 'john@example.com' })
emit('custom', { id: 1, action: 'delete' })
```

### 2. Slots and Scoped Slots

**Named Slots Pattern**:

```vue
<!-- DataTable.vue -->
<script setup lang="ts">
defineProps<{
  data: any[]
  loading?: boolean
}>()

defineSlots<{
  default(): any
  header(): any
  'cell'({ row, column, value }: { row: any; column: string; value: any }): any
  actions({ row }: { row: any }): any
}>()
</script>

<template>
  <div class="data-table">
    <slot name="header" />

    <table>
      <thead>
        <tr>
          <slot name="thead" />
        </tr>
      </thead>
      <tbody>
        <tr v-for="row in data" :key="row.id">
          <slot name="cell" :row="row" column="default" :value="row">
            {{ value }}
          </slot>
          <slot name="actions" :row="row" />
        </tr>
      </tbody>
    </table>
  </div>
</template>
```

**Usage**:

```vue
<DataTable :data="users" :loading="isLoading">
  <template #header>
    <h2>Users</h2>
  </template>

  <template #thead>
    <th>Name</th>
    <th>Email</th>
    <th>Actions</th>
  </template>

  <template #cell="{ row, column }">
    <td v-if="column === 'name'">{{ row.name }}</td>
    <td v-else-if="column === 'email'">{{ row.email }}</td>
  </template>

  <template #actions="{ row }">
    <td>
      <button @click="editUser(row)">Edit</button>
      <button @click="deleteUser(row)">Delete</button>
    </td>
  </template>
</DataTable>
```

### 3. Dependency Injection

**Provide/Inject Pattern**:

```typescript
// composables/useTheme.ts
import { inject, provide, readonly, type InjectionKey } from 'vue'

interface Theme {
  primaryColor: string
  secondaryColor: string
  darkMode: boolean
  toggleDarkMode: () => void
}

const themeKey: InjectionKey<Theme> = Symbol('theme')

export function provideTheme() {
  const primaryColor = ref('#007bff')
  const secondaryColor = ref('#6c757d')
  const darkMode = ref(false)

  const toggleDarkMode = () => {
    darkMode.value = !darkMode.value
  }

  const theme: Theme = {
    primaryColor: readonly(primaryColor) as string,
    secondaryColor: readonly(secondaryColor) as string,
    darkMode: readonly(darkMode) as boolean,
    toggleDarkMode
  }

  provide(themeKey, theme)

  return theme
}

export function useTheme(): Theme {
  const theme = inject(themeKey)
  if (!theme) {
    throw new Error('Theme not provided')
  }
  return theme
}
```

## Performance Optimization

### 1. Lazy Loading Components

```vue
<script setup lang="ts">
import { defineAsyncComponent } from 'vue'
import LoadingSpinner from '@/components/LoadingSpinner.vue'
import ErrorBoundary from '@/components/ErrorBoundary.vue'

// Lazy load heavy components
const HeavyChart = defineAsyncComponent({
  loader: () => import('@/components/HeavyChart.vue'),
  loadingComponent: LoadingSpinner,
  errorComponent: ErrorBoundary,
  delay: 200,
  timeout: 3000
})

// With suspense-compatible setup
const AsyncModal = defineAsyncComponent(() =>
  import('@/components/Modal.vue')
)
</script>
```

### 2. Virtual Scrolling

```vue
<script setup lang="ts">
import { ref } from 'vue'
import { useVirtualList } from '@vueuse/core'

const items = ref([...Array(10000).keys()].map(i => ({ id: i, text: `Item ${i}` })))

const {
  list,
  containerProps,
  wrapperProps
} = useVirtualList(items, {
  itemHeight: 50,
  overscan: 10
})
</script>

<template>
  <div v-bind="containerProps" class="virtual-list">
    <div v-bind="wrapperProps">
      <div v-for="{ data, index } in list" :key="data.id">
        {{ data.text }} - Index: {{ index }}
      </div>
    </div>
  </div>
</template>
```

### 3. Memoization and Caching

```typescript
// composables/useDebounce.ts
import { ref, watch } from 'vue'

export function useDebouncedRef<T>(initialValue: T, delay: number = 300) {
  const value = ref<T>(initialValue)
  const debouncedValue = ref<T>(initialValue)

  let timeout: ReturnType<typeof setTimeout>

  watch(value, (newValue) => {
    clearTimeout(timeout)
    timeout = setTimeout(() => {
      debouncedValue.value = newValue
    }, delay)
  })

  return { value, debouncedValue }
}

// composables/useMemo.ts
export function useMemo<T>(factory: () => T, deps: unknown[]): Readonly<Ref<T>> {
  const value = ref<T>() as Ref<T>
  let oldDeps: unknown[] | undefined

  const update = () => {
    if (!oldDeps || !depsEqual(deps, oldDeps)) {
      value.value = factory()
      oldDeps = deps
    }
  }

  update()

  return value as Readonly<Ref<T>>
}
```

## Security Best Practices

### 1. XSS Prevention

```typescript
// Never use v-html with user-provided content
// BAD
const userContent = '<script>alert("xss")</script>'
// <div v-html="userContent"></div>

// GOOD: Sanitize first
import DOMPurify from 'dompurify'

const sanitizedContent = computed(() =>
  DOMPurify.sanitize(userContent.value)
)

// Then use
// <div v-html="sanitizedContent"></div>

// For rich text, use a safe library like TipTap or Quill
```

### 2. Input Validation

```typescript
// composables/useFormValidation.ts
import { ref, computed, type Ref } from 'vue'

interface ValidationRule {
  validate: (value: unknown) => boolean
  message: string
}

export function useFormValidation<T extends Record<string, unknown>>(
  initialValues: T,
  rules: Record<keyof T, ValidationRule[]>
) {
  const values = ref(initialValues) as Ref<T>
  const errors = ref<Partial<Record<keyof T, string>>>({})

  const validate = (field?: keyof T): boolean => {
    if (field) {
      return validateField(field)
    }

    let isValid = true
    for (const key in rules) {
      if (!validateField(key)) {
        isValid = false
      }
    }
    return isValid
  }

  const validateField = (field: keyof T): boolean => {
    const fieldRules = rules[field]
    if (!fieldRules) return true

    for (const rule of fieldRules) {
      if (!rule.validate(values.value[field])) {
        errors.value[field] = rule.message
        return false
      }
    }

    errors.value[field] = undefined
    return true
  }

  const reset = () => {
    values.value = { ...initialValues }
    errors.value = {}
  }

  return {
    values,
    errors,
    validate,
    validateField,
    reset
  }
}

// Usage
const { values, errors, validate } = useFormValidation(
  { email: '', password: '' },
  {
    email: [
      { validate: v => !!v, message: 'Email is required' },
      { validate: v => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v), message: 'Invalid email' }
    ],
    password: [
      { validate: v => v.length >= 8, message: 'Password must be at least 8 characters' }
    ]
  }
)
```

## Testing Best Practices

### 1. Component Testing

```typescript
// components/UserCard.spec.ts
import { describe, it, expect } from 'vitest'
import { mount } from '@vue/test-utils'
import UserCard from './UserCard.vue'

describe('UserCard', () => {
  const mockUser = {
    id: 1,
    name: 'John Doe',
    email: 'john@example.com',
    role: 'admin'
  }

  it('renders user information correctly', () => {
    const wrapper = mount(UserCard, {
      props: {
        user: mockUser,
        showActions: true
      }
    })

    expect(wrapper.find('.user-card__name').text()).toBe('John Doe')
    expect(wrapper.find('.user-card__email').text()).toBe('john@example.com')
  })

  it('emits select event when clicked', async () => {
    const wrapper = mount(UserCard, {
      props: { user: mockUser }
    })

    await wrapper.find('button').trigger('click')

    expect(wrapper.emitted('select')?.[0]).toEqual([mockUser.id])
  })

  it('respects showActions prop', () => {
    const withActions = mount(UserCard, {
      props: { user: mockUser, showActions: true }
    })

    const withoutActions = mount(UserCard, {
      props: { user: mockUser, showActions: false }
    })

    expect(withActions.find('.user-card__actions').exists()).toBe(true)
    expect(withoutActions.find('.user-card__actions').exists()).toBe(false)
  })
})
```

### 2. Composables Testing

```typescript
// composables/useCounter.spec.ts
import { describe, it, expect } from 'vitest'
import { useCounter } from './useCounter'

describe('useCounter', () => {
  it('initializes with default value', () => {
    const { count } = useCounter()
    expect(count.value).toBe(0)
  })

  it('accepts custom initial value', () => {
    const { count } = useCounter(10)
    expect(count.value).toBe(10)
  })

  it('respects min and max bounds', () => {
    const { count, increment, decrement, isAtMin, isAtMax } = useCounter(5, {
      min: 0,
      max: 10
    })

    // Test max boundary
    for (let i = 0; i < 10; i++) increment()
    expect(count.value).toBe(10)
    expect(isAtMax.value).toBe(true)

    // Test min boundary
    for (let i = 0; i < 20; i++) decrement()
    expect(count.value).toBe(0)
    expect(isAtMin.value).toBe(true)
  })

  it('resets to initial value', () => {
    const { count, increment, reset } = useCounter(0)
    increment()
    increment()
    expect(count.value).toBe(2)
    reset()
    expect(count.value).toBe(0)
  })
})
```

## Examples

### Complete Component Example

```vue
<script setup lang="ts">
import { ref, computed, watch, onMounted } from 'vue'
import { useAuthStore } from '@/stores/auth'
import { useNotifications } from '@/composables/useNotifications'

interface Props {
  taskId: number
}

const props = defineProps<Props>()

const emit = defineEmits<{
  complete: [taskId: number]
  delete: [taskId: number]
  update: [taskId: number, updates: Partial<Task>]
}>()

// Stores and composables
const authStore = useAuthStore()
const notifications = useNotifications()

// Local state
const isEditing = ref(false)
const editForm = ref({
  title: '',
  description: '',
  priority: 'medium' as 'low' | 'medium' | 'high',
  dueDate: ''
})

// Computed
const canEdit = computed(() =>
  authStore.currentUser?.id === props.task?.assigneeId ||
  authStore.hasPermission('tasks.edit')
)

// Watchers
watch(() => props.task, (newTask) => {
  if (newTask) {
    editForm.value = {
      title: newTask.title,
      description: newTask.description,
      priority: newTask.priority,
      dueDate: newTask.dueDate
    }
  }
}, { immediate: true })

// Methods
const startEditing = () => {
  editForm.value = {
    title: props.task?.title ?? '',
    description: props.task?.description ?? '',
    priority: props.task?.priority ?? 'medium',
    dueDate: props.task?.dueDate ?? ''
  }
  isEditing.value = true
}

const cancelEditing = () => {
  isEditing.value = false
}

const saveChanges = () => {
  emit('update', props.taskId, editForm.value)
  notifications.success('Task updated successfully')
  isEditing.value = false
}

const markComplete = () => {
  emit('complete', props.taskId)
  notifications.success('Task marked as complete')
}

const deleteTask = () => {
  if (confirm('Are you sure you want to delete this task?')) {
    emit('delete', props.taskId)
    notifications.success('Task deleted')
  }
}

// Lifecycle
onMounted(() => {
  // Load task data if needed
})
</script>

<template>
  <article class="task-card" :class="`task-card--${task?.priority}`">
    <header class="task-card__header">
      <h3 class="task-card__title">{{ task?.title }}</h3>
      <span class="task-card__priority">{{ task?.priority }}</span>
    </header>

    <p v-if="task?.description" class="task-card__description">
      {{ task?.description }}
    </p>

    <footer class="task-card__footer">
      <span v-if="task?.dueDate" class="task-card__due-date">
        Due: {{ formatDate(task.dueDate) }}
      </span>

      <div v-if="canEdit && !isEditing" class="task-card__actions">
        <button @click="startEditing">Edit</button>
        <button @click="markComplete">Complete</button>
        <button @click="deleteTask" class="danger">Delete</button>
      </div>
    </footer>

    <!-- Edit Form -->
    <form v-if="isEditing" class="task-card__edit-form" @submit.prevent="saveChanges">
      <label>
        Title
        <input v-model="editForm.title" type="text" required />
      </label>

      <label>
        Description
        <textarea v-model="editForm.description"></textarea>
      </label>

      <label>
        Priority
        <select v-model="editForm.priority">
          <option value="low">Low</option>
          <option value="medium">Medium</option>
          <option value="high">High</option>
        </select>
      </label>

      <div class="form-actions">
        <button type="button" @click="cancelEditing">Cancel</button>
        <button type="submit">Save</button>
      </div>
    </form>
  </article>
</template>
```

## References

### Official Resources

- Vue 3 Documentation: https://vuejs.org/
- Vue Router Documentation: https://router.vuejs.org/
- Pinia Documentation: https://pinia.vuejs.org/
- Vue Test Utils: https://test-utils.vuejs.org/

### Recommended Tools

- Vite: Fast build tool (https://vitejs.dev/)
- Vitest: Unit testing framework (https://vitest.dev/)
- Volar: VS Code extension (https://marketplace.visualstudio.com/items?itemName=Vue.volar)
- Vue DevTools: Browser extension

### Further Learning

- Vue.js Design Patterns (O'Reilly)
- Building Vue 3 Applications (Packt)
- Vue School Courses (https://vueschool.io/)

## Kết Luận

Áp dụng các best practices trong tài liệu này sẽ giúp bạn xây dựng Vue applications chất lượng cao. Tuy nhiên, quan trọng cần nhớ:

1. **Consistency quan trọng hơn perfection** - một codebase consistent với một số imperfect patterns tốt hơn một codebase inconsistent với perfect patterns.

2. **Context matters** - không phải mọi pattern đều phù hợp cho mọi situation. Evaluate case by case.

3. **Iterate and improve** - không cần phải apply tất cả cùng lúc. Bắt đầu với những thay đổi có impact cao và iterate.

4. **Document your decisions** - khi deviate từ standard practices, document lý do để team members hiểu.

5. **Stay updated** - Vue ecosystem evolving rapidly. Theo dõi changelog và official recommendations.

Với commitment to quality và continuous improvement, bạn sẽ có thể xây dựng những Vue applications xuất sắc.

glossary.content:
---
title: "Vue Glossary - Từ Điển Thuật Ngữ Vue.js"
description: "Từ điển toàn diện các thuật ngữ chuyên ngành Vue.js với giải thích chi tiết bằng tiếng Việt và tiếng Anh"
tags: ["vue", "javascript", "glossary", "terminology", "reference"]
created: "2026-06-23"
version: "1.0.0"
framework: "cursor-enterprise-framework"
---

# Vue Glossary - Từ Điển Thuật Ngữ Vue.js

## Tổng Quan

Tài liệu này cung cấp một từ điển toàn diện các thuật ngữ chuyên ngành được sử dụng trong Vue.js ecosystem. Mỗi thuật ngữ được định nghĩa chi tiết với ngữ cảnh sử dụng, ví dụ code, và cross-references đến các thuật ngữ liên quan.

Vue.js là một framework progressive với một hệ sinh thái phong phú, và việc hiểu đúng các thuật ngữ là nền tảng cho việc sử dụng hiệu quả. Từ điển này được thiết kế để serve như một reference guide cho cả beginners lẫn experienced developers.

Các thuật ngữ được tổ chức theo categories để dễ navigation. Cross-references được provided để help connect related concepts. Examples được provided trong TypeScript/Vue 3 syntax.

## Mục Đích

1. **Standardize Terminology**: Cung cấp consistent definitions cho Vue terminology trong team. Khi everyone shares common understanding, communication becomes clearer.

2. **Onboarding Support**: Giúp new team members quickly understand Vue terminology. Từ điển này có thể được sử dụng như reference during onboarding.

3. **Knowledge Reference**: Serve như quick reference khi encountering unfamiliar terms. Useful khi reading Vue documentation hoặc tutorials.

4. **Bilingual Support**: Cung cấp explanations trong cả tiếng Việt (cho khái niệm) và tiếng Anh (cho technical terms và code).

## A

### Abstract Syntax Tree (AST)

**Định nghĩa**: Một biểu diễn cấu trúc dữ liệu của code ở dạng tree structure, where mỗi node đại diện cho một construct trong source code như expressions, statements, hoặc declarations.

**Trong Vue Context**: Vue compiler chuyển đổi template strings thành AST trước khi tạo ra render functions hoặc JavaScript code. AST allows Vue's compiler thực hiện optimizations và transformations.

**Ví dụ**:

```typescript
// Template được parse thành AST
const template = '<div class="container">{{ message }}</div>'

// Vue compiler tạo ra AST structure
const ast = {
  type: 'Element',
  tag: 'div',
  props: [
    { type: 'Attribute', name: 'class', value: 'container' }
  ],
  children: [
    {
      type: 'Interpolation',
      content: { type: 'Expression', value: 'message' }
    }
  ]
}
```

**Xem thêm**: Template Compilation, Virtual DOM

### Async Component

**Định nghĩa**: Một component được loaded asynchronously khi cần thiết, thay vì bundle cùng với main application bundle. Async components giúp reduce initial bundle size và improve load time.

**Trong Vue Context**: Sử dụng `defineAsyncComponent` để define async components. Useful cho code splitting và lazy loading.

**Ví dụ**:

```typescript
import { defineAsyncComponent } from 'vue'

// Basic async component
const AsyncModal = defineAsyncComponent(() =>
  import('./components/Modal.vue')
)

// Với loading và error states
const AsyncDashboard = defineAsyncComponent({
  loader: () => import('./pages/Dashboard.vue'),
  loadingComponent: LoadingSpinner,
  errorComponent: ErrorFallback,
  delay: 200,
  timeout: 3000
})
```

**Xem thêm**: Code Splitting, Lazy Loading

## B

### Bootstrap

**Định nghĩa**: Quá trình khởi tạo và prepare một Vue application để chạy, bao gồm việc setup plugins, stores, và router.

**Trong Vue Context**: Thường xảy ra trong `main.ts` hoặc `main.js` file, nơi Vue app được created và mounted.

**Ví dụ**:

```typescript
// main.ts
import { createApp } from 'vue'
import { createPinia } from 'pinia'
import router from './router'
import App from './App.vue'

const app = createApp(App)

// Bootstrap process
app.use(createPinia())
app.use(router)
app.mount('#app')
```

**Xem thêm**: Application Instance, Plugin

### Build Tool

**Định nghĩa**: Tool được sử dụng để bundle, compile, và transform Vue application code thành production-ready artifacts. Common build tools cho Vue bao gồm Vite, Webpack (thông qua Vue CLI), và Rollup.

**Trong Vue Context**: Build tools handle template compilation, TypeScript transpilation, CSS preprocessing, và asset optimization.

**Ví dụ**:

```typescript
// vite.config.ts
import { defineConfig } from 'vite'
import vue from '@vitejs/plugin-vue'
import { resolve } from 'path'

export default defineConfig({
  plugins: [vue()],
  resolve: {
    alias: {
      '@': resolve(__dirname, 'src')
    }
  },
  build: {
    sourcemap: true,
    rollupOptions: {
      output: {
        manualChunks: {
          vendor: ['vue', 'vue-router', 'pinia']
        }
      }
    }
  }
})
```

**Xem thêm**: Vite, Webpack, Vue CLI

## C

### Component (Thành Phần)

**Định nghĩa**: Khối xây dựng cơ bản trong Vue.js, là một self-contained unit của UI có thể tái sử dụng. Mỗi component encapsulates its own template, logic, và styles.

**Trong Vue Context**: Components có thể be nested để tạo thành component tree. Chúng communicate qua props, emits, slots, và dependency injection.

**Ví dụ**:

```vue
<script setup lang="ts">
import { ref } from 'vue'

interface Props {
  title: string
  count?: number
}

const props = withDefaults(defineProps<Props>(), {
  count: 0
})

const emit = defineEmits<{
  update: [value: number]
}>()

const localCount = ref(props.count)

const increment = () => {
  localCount.value++
  emit('update', localCount.value)
}
</script>

<template>
  <div class="counter">
    <h2>{{ title }}</h2>
    <p>Count: {{ localCount }}</p>
    <button @click="increment">Increment</button>
  </div>
</template>

<style scoped>
.counter {
  padding: 1rem;
  border: 1px solid #ddd;
  border-radius: 8px;
}
</style>
```

**Xem thêm**: Single-File Component, Component Instance

### Component Instance

**Định nghĩa**: Một runtime instance của một Vue component, được tạo ra khi component được rendered. Mỗi instance có its own reactive state, computed properties, watchers, và lifecycle hooks.

**Trong Vue Context**: Trong Vue 3 với Composition API, component instance được tự động tạo khi sử dụng `<script setup>`. Trong Options API, instance được tạo và các options được merged.

**Ví dụ**:

```typescript
// Accessing component instance
const MyComponent = {
  setup() {
    // In Composition API, this is automatic
    const message = ref('Hello')

    return { message }
  }
}

// Accessing via ref
const componentRef = ref<InstanceType<typeof MyComponent> | null>(null)

// Accessing via $refs (Options API)
const myComponent = this.$refs.myComponent as InstanceType<typeof MyComponent>
```

**Xem thêm**: Component, Reactive System

### Composition API

**Định nghĩa**: Một set của APIs cho phép developers organize component logic sử dụng imported functions thay vì options objects. Introduced trong Vue 3 như một alternative cho Options API.

**Trong Vue Context**: Composition API cung cấp better TypeScript support, better code reuse (through composables), và better organization cho complex components.

**Core Functions**:

```typescript
import {
  ref,           // Tạo reactive reference
  reactive,      // Tạo reactive object
  computed,      // Tạo computed property
  watch,         // Watch for changes
  watchEffect,   // Watch with immediate effect
  onMounted,     // Lifecycle hook
  onUnmounted,   // Lifecycle hook
  provide,       // Provide for descendants
  inject,        // Inject from ancestors
  defineProps,   // Define props
  defineEmits,   // Define emits
  defineExpose    // Expose public interface
} from 'vue'
```

**Ví dụ**:

```vue
<script setup lang="ts">
import { ref, computed, onMounted } from 'vue'

// Reactive state
const count = ref(0)
const user = reactive({ name: 'John', age: 30 })

// Computed
const doubled = computed(() => count.value * 2)

// Method
const increment = () => {
  count.value++
}

// Lifecycle
onMounted(() => {
  console.log('Component mounted')
})
</script>
```

**Xem thêm**: Options API, Composable, Reactivity System

### Computed Property

**Định nghĩa**: Một reactive property được derived tự động từ other reactive data. Computed properties are cached và chỉ re-evaluate khi dependencies thay đổi.

**Trong Vue Context**: Computed properties perfect cho derived state - data được calculate từ other state mà không cần manual synchronization.

**Ví dụ**:

```typescript
import { ref, computed } from 'vue'

const firstName = ref('John')
const lastName = ref('Doe')

// Computed property
const fullName = computed(() => {
  return `${firstName.value} ${lastName.value}`
})

// Computed với setter
const fullNameWithSetter = computed({
  get: () => `${firstName.value} ${lastName.value}`,
  set: (value: string) => {
    const [first, last] = value.split(' ')
    firstName.value = first
    lastName.value = last
  }
})
```

**Xem thêm**: Reactivity, Watcher, Getter

### Custom Directive

**Định nghĩa**: Một directive mà developers có thể register để perform custom DOM manipulation. Directives cung cấp a way để attach reusable behavior đến elements.

**Trong Vue Context**: Vue có một số built-in directives như `v-bind`, `v-model`, `v-if`. Custom directives cho phép extend Vue's template capabilities.

**Lifecycle Hooks**:

```typescript
const myDirective = {
  // Called before parent component mounted
  created(el, binding, vnode, prevVnode) {},

  // Called before element inserted into DOM
  beforeMount(el, binding, vnode, prevVnode) {},

  // Called when element is mounted
  mounted(el, binding, vnode, prevVnode) {},

  // Called before parent component updates
  beforeUpdate(el, binding, vnode, prevVnode) {},

  // Called when component updates
  updated(el, binding, vnode, prevVnode) {},

  // Called before parent component unmounts
  beforeUnmount(el, binding, vnode, prevVnode) {},

  // Called when element is unmounted
  unmounted(el, binding, vnode, prevVnode) {}
}
```

**Registration**:

```typescript
// Global
app.directive('focus', myDirective)

// Local
const vFocus = {
  mounted: (el) => el.focus()
}
```

**Xem thêm**: Directive, Built-in Directive

## D

### Dependency Injection

**Định nghĩa**: Một pattern trong đó một component provides data hoặc services mà descendants có thể consume without explicit passing qua props chain. Vue implement this qua provide/inject.

**Trong Vue Context**: Useful cho passing data through deep component trees mà không cần prop drilling. Common use cases bao gồm theme configuration, authentication state, và feature flags.

**Ví dụ**:

```typescript
// Provider (ancestor component)
import { provide, ref } from 'vue'

const theme = ref('light')

provide('theme', {
  current: theme,
  toggleTheme: () => {
    theme.value = theme.value === 'light' ? 'dark' : 'light'
  }
})

// Consumer (descendant component)
import { inject } from 'vue'

const theme = inject('theme')

// With default value và type safety
interface ThemeContext {
  current: Ref<string>
  toggleTheme: () => void
}

const theme = inject<ThemeContext>('theme', {
  current: ref('light'),
  toggleTheme: () => {}
})
```

**Xem thêm**: Provide/Inject, Prop Drilling

### Directive (Chỉ Thị)

**Định nghĩa**: Special attributes prefixed với `v-` cung cấp declarative binding giữa data và DOM. Directives có thể perform DOM manipulation, handle events, hoặc apply conditional rendering.

**Trong Vue Context**: Built-in directives bao gồm `v-if`, `v-for`, `v-bind`, `v-on`, `v-model`, `v-show`, `v-slot`, `v-cloak`, `v-once`, và `v-memo`.

**Ví dụ**:

```vue
<template>
  <!-- v-bind - one-way binding -->
  <img v-bind:src="imageUrl" :alt="description" />

  <!-- v-on - event binding -->
  <button v-on:click="handleClick" @keyup.enter="handleEnter">
    Click me
  </button>

  <!-- v-model - two-way binding -->
  <input v-model="searchQuery" />

  <!-- v-if/v-else - conditional -->
  <div v-if="isLoggedIn">Welcome</div>
  <div v-else>Please login</div>

  <!-- v-for - list rendering -->
  <li v-for="item in items" :key="item.id">{{ item.name }}</li>

  <!-- v-show - visibility toggle -->
  <div v-show="isVisible">Content</div>
</template>
```

**Xem thêm**: Built-in Directive, Custom Directive

### Dynamic Component

**Định nghĩa**: Một component được resolved dynamically dựa trên runtime data, sử dụng `<component :is="...">` syntax. Cho phép switch between different components without changing the route.

**Trong Vue Context**: Useful cho tabbed interfaces, component switching based on user input, và dynamic layouts.

**Ví dụ**:

```vue
<script setup lang="ts">
import { ref, shallowRef } from 'vue'
import HomeTab from './tabs/HomeTab.vue'
import ProfileTab from './tabs/ProfileTab.vue'
import SettingsTab from './tabs/SettingsTab.vue'

const activeTab = ref('home')
const tabs = {
  home: HomeTab,
  profile: ProfileTab,
  settings: SettingsTab
}
</script>

<template>
  <div class="tab-container">
    <button
      v-for="(_, key) in tabs"
      :key="key"
      :class="{ active: activeTab === key }"
      @click="activeTab = key as string"
    >
      {{ key }}
    </button>

    <component :is="tabs[activeTab]" />
  </div>
</template>
```

