### Common Error Messages và Solutions

**"Avoid mutating a prop directly"**:

```typescript
// Error: Props are readonly
// Solution: Use local copy or emit events
const props = defineProps<{ modelValue: number }>()
const emit = defineEmits<{ 'update:modelValue': [number] }>()

const localValue = ref(props.modelValue)

watch(() => props.modelValue, (v) => {
  localValue.value = v
})

const update = (newVal: number) => {
  localValue.value = newVal
  emit('update:modelValue', newVal)
}
```

**"Computed property was assigned to but it has no setter"**:

```typescript
// Error: Trying to assign to read-only computed
// Solution: Define both getter and setter if needed
const fullName = computed({
  get: () => `${firstName.value} ${lastName.value}`,
  set: (value: string) => {
    const [first, last] = value.split(' ')
    firstName.value = first
    lastName.value = last
  }
})
```

## Examples

### Complete Example: Well-Structured Vue Component

```vue
<script setup lang="ts">
import { ref, computed, watch, onMounted, onUnmounted } from 'vue'
import { useUserStore } from '@/stores/user'
import { useNotifications } from '@/composables/useNotifications'

interface Props {
  userId: number
  editable?: boolean
}

const props = withDefaults(defineProps<Props>(), {
  editable: false
})

const emit = defineEmits<{
  update: [user: Partial<User>]
  delete: [userId: number]
}>()

// Store integration
const userStore = useUserStore()
const notifications = useNotifications()

// Local state
const isLoading = ref(true)
const isEditing = ref(false)
const formData = reactive({
  name: '',
  email: '',
  bio: ''
})

// Computed properties
const user = computed(() =>
  userStore.getUserById(props.userId)
)

const hasUnsavedChanges = computed(() =>
  formData.name !== user.value?.name ||
  formData.email !== user.value?.email ||
  formData.bio !== user.value?.bio
)

// Methods
const startEditing = () => {
  if (!props.editable) return

  formData.name = user.value?.name || ''
  formData.email = user.value?.email || ''
  formData.bio = user.value?.bio || ''
  isEditing.value = true
}

const cancelEditing = () => {
  isEditing.value = false
}

const saveChanges = async () => {
  try {
    await userStore.updateUser(props.userId, formData)
    emit('update', formData)
    notifications.success('User updated successfully')
    isEditing.value = false
  } catch (error) {
    notifications.error('Failed to update user')
  }
}

const confirmDelete = () => {
  if (confirm('Are you sure you want to delete this user?')) {
    emit('delete', props.userId)
  }
}

// Watchers for side effects
watch(() => props.userId, async (newId) => {
  isLoading.value = true
  await userStore.fetchUser(newId)
  isLoading.value = false
}, { immediate: true })

// Lifecycle
onMounted(() => {
  window.addEventListener('keydown', handleKeydown)
})

onUnmounted(() => {
  window.removeEventListener('keydown', handleKeydown)
})

const handleKeydown = (e: KeyboardEvent) => {
  if (e.key === 'Escape' && isEditing.value) {
    cancelEditing()
  }
}
</script>

<template>
  <div class="user-profile">
    <div v-if="isLoading" class="loading">
      Loading...
    </div>

    <template v-else-if="user">
      <div class="profile-header">
        <img :src="user.avatar" :alt="user.name" class="avatar" />
        <div class="info">
          <h2>{{ user.name }}</h2>
          <p>{{ user.email }}</p>
        </div>
        <button
          v-if="editable && !isEditing"
          @click="startEditing"
        >
          Edit
        </button>
      </div>

      <div v-if="isEditing" class="edit-form">
        <label>
          Name
          <input v-model="formData.name" type="text" />
        </label>
        <label>
          Email
          <input v-model="formData.email" type="email" />
        </label>
        <label>
          Bio
          <textarea v-model="formData.bio"></textarea>
        </label>
        <div class="actions">
          <button @click="cancelEditing">Cancel</button>
          <button
            @click="saveChanges"
            :disabled="!hasUnsavedChanges"
          >
            Save
          </button>
        </div>
      </div>

      <div v-else class="bio">
        {{ user.bio || 'No bio provided' }}
      </div>
    </template>

    <div v-else class="not-found">
      User not found
    </div>
  </div>
</template>

<style scoped>
.user-profile {
  max-width: 600px;
  margin: 0 auto;
}

.profile-header {
  display: flex;
  align-items: center;
  gap: 16px;
}

.avatar {
  width: 80px;
  height: 80px;
  border-radius: 50%;
}

.edit-form label {
  display: block;
  margin-bottom: 12px;
}

.edit-form input,
.edit-form textarea {
  width: 100%;
  padding: 8px;
  margin-top: 4px;
}

.actions {
  display: flex;
  gap: 8px;
  justify-content: flex-end;
}
</style>
```

